def shortestPalindrome(s):
    def is_palindrome(s):
        return s == s[::-1]

    for i in range(len(s)):
        if is_palindrome(s[i:]):
            return s[::-1][:len(s) - i] + s

    return ""

# Example usage:
print(shortestPalindrome("aacecaaa"))  # Output: "aaacecaaa"
print(shortestPalindrome("abcd"))      # Output: "dcbabcd"
